package com.acme.travel.hotels;

import java.time.LocalDate;

/**
 * Checks nightly availability across a stay before confirming a hotel booking.
 */
public class RoomAvailabilityGuard {

    private final InventoryRepository inventory;

    public RoomAvailabilityGuard(InventoryRepository inventory) {
        this.inventory = inventory;
    }

    public void assertAvailable(String hotelId, String roomType, LocalDate checkIn, LocalDate checkOut) {
        LocalDate night = checkIn;
        while (night.isBefore(checkOut)) {
            int remaining = inventory.remaining(hotelId, roomType, night);
            if (remaining <= 0) {
                throw new NoAvailabilityException(hotelId, roomType, night);
            }
            night = night.plusDays(1);
        }
    }
}

class NoAvailabilityException extends RuntimeException {
    public NoAvailabilityException(String hotelId, String roomType, LocalDate night) {
        super("No " + roomType + " at " + hotelId + " on " + night);
    }
}

