package com.acme.travel.hotels;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;

/**
 * Sums nightly rates over the stay, then applies taxes and extras.
 */
public class HotelPriceCalculator {

    private final RateTable rates;
    private final TaxTable taxes;

    public HotelPriceCalculator(RateTable rates, TaxTable taxes) {
        this.rates = rates;
        this.taxes = taxes;
    }

    public BigDecimal total(String hotelId, String roomType, LocalDate in, LocalDate out,
                            List<Extra> extras) {
        BigDecimal nightly = BigDecimal.ZERO;
        LocalDate night = in;
        while (night.isBefore(out)) {
            nightly = nightly.add(rates.nightlyRate(hotelId, roomType, night));
            night = night.plusDays(1);
        }
        BigDecimal extrasTotal = extras.stream().map(Extra::getPrice)
            .reduce(BigDecimal.ZERO, BigDecimal::add);
        BigDecimal tax = taxes.forStay(hotelId, nightly);
        return nightly.add(extrasTotal).add(tax).setScale(2, RoundingMode.HALF_UP);
    }
}

