/**
 * Flight search endpoint returning matching itineraries sorted by price.
 */
@RestController
public class FlightSearchController {

    private final FlightInventory inventory;
    private final FareCalculator fares;

    public FlightSearchController(FlightInventory inventory, FareCalculator fares) {
        this.inventory = inventory;
        this.fares = fares;
    }

    @GetMapping("/flights/search")
    public List<FlightOption> search(@RequestParam String origin,
                                     @RequestParam String destination,
                                     @RequestParam LocalDate depart,
                                     @RequestParam(required = false) LocalDate returnDate) {
        List<Flight> found = inventory.find(origin, destination, depart, returnDate);
        return found.stream()
            .map(f -> new FlightOption(f, fares.total(f)))
            .sorted(Comparator.comparing(FlightOption::getTotalPrice))
            .collect(Collectors.toList());
    }
}

