/**
 * Bundles a return flight and a hotel stay into a single package booking.
 */
public class PackageBookingService {

    private final FlightBookingService flights;
    private final HotelBookingService hotels;
    private final PackageRepository packages;
    private final PaymentProcessor payments;

    public PackageBookingService(FlightBookingService flights, HotelBookingService hotels,
                                 PackageRepository packages, PaymentProcessor payments) {
        this.flights = flights;
        this.hotels = hotels;
        this.packages = packages;
        this.payments = payments;
    }

    public PackageReceipt book(String travellerId, String outboundFlightId, String returnFlightId,
                               String hotelId, String roomType, java.time.LocalDate in, java.time.LocalDate out) {
        FlightBooking out = flights.reserve(outboundFlightId, travellerId);
        FlightBooking ret = flights.reserve(returnFlightId, travellerId);
        HotelBooking hotel = hotels.reserve(hotelId, roomType, in, out, travellerId);
        payments.charge(travellerId, out.getPrice().add(ret.getPrice()).add(hotel.getPrice()));
        return packages.save(Package.of(travellerId, List.of(out, ret), hotel));
    }
}

