package com.acme.travel.flights;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * Cancels a flight booking and calculates refund per the fare rules.
 */
public class FlightCancellationService {

    private final BookingRepository bookings;
    private final RefundProcessor refunds;

    public FlightCancellationService(BookingRepository bookings, RefundProcessor refunds) {
        this.bookings = bookings;
        this.refunds = refunds;
    }

    public RefundReceipt cancel(String bookingId, String reason) {
        FlightBooking booking = bookings.require(bookingId);
        if (booking.getStatus() != BookingStatus.CONFIRMED) {
            throw new IllegalStateException("Only confirmed bookings may be cancelled");
        }
        BigDecimal refund = booking.getFareRules().refundFor(booking.getTotal(), booking.getDepartAt(), Instant.now());
        booking.cancel(reason, Instant.now());
        bookings.save(booking);
        return refunds.issue(booking.getTravellerId(), refund);
    }
}

