import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

/**
 * Applies a late change fee on hotel bookings moved close to arrival.
 */
public class HotelChangeFeePolicy {

    private static final long FEE_DAYS_THRESHOLD = 7;

    private final BigDecimal changeFee;

    public HotelChangeFeePolicy(BigDecimal changeFee) {
        this.changeFee = changeFee;
    }

    public BigDecimal feeFor(LocalDate originalCheckIn, LocalDate newCheckIn, LocalDate today) {
        if (!newCheckIn.isAfter(originalCheckIn)) {
            return BigDecimal.ZERO;
        }
        long daysUntilArrival = ChronoUnit.DAYS.between(today, originalCheckIn);
        return daysUntilArrival < FEE_DAYS_THRESHOLD ? changeFee : BigDecimal.ZERO;
    }
}

