/**
 * Issues and persists an e-ticket for a confirmed flight booking.
 */
public class ETicketIssuer {

    private final TicketNumberGenerator generator;
    private final ETicketRepository tickets;

    public ETicketIssuer(TicketNumberGenerator generator, ETicketRepository tickets) {
        this.generator = generator;
        this.tickets = tickets;
    }

    public ETicket issueFor(FlightBooking booking) {
        if (booking.getStatus() != BookingStatus.CONFIRMED) {
            throw new IllegalStateException("Cannot issue ticket for " + booking.getStatus());
        }
        ETicket ticket = new ETicket();
        ticket.setBookingId(booking.getId());
        ticket.setTicketNumber(generator.next());
        ticket.setIssuedAt(Instant.now());
        ticket.setTravellerId(booking.getTravellerId());
        return tickets.save(ticket);
    }
}

