/* dynamic_rate.c - compute per-night rate with weekend and peak-season uplift */
#include <stdio.h>
#include "travel_db.h"

int nightly_rate(const char *hotel_id, const char *room_type, const char *date, double *out_rate) {
    double base = 0.0;
    if (db_lookup_base_rate(hotel_id, room_type, &base) != DB_OK) return -1;

    struct tm tm_date;
    if (parse_iso_date(date, &tm_date) != 0) return -2;

    int weekend = (tm_date.tm_wday == 0 || tm_date.tm_wday == 6);
    if (weekend) base *= 1.15;

    int peak = 0;
    if (db_is_peak_season(hotel_id, date, &peak) != DB_OK) return -3;
    if (peak) base *= 1.25;

    *out_rate = base;
    return 0;
}

